```java
package com.projectilesim;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.utils.Array;
import com.badlogic.gdx.utils.Pool;
import java.io.BufferedReader;
import java.io.Writer;
import java.io.FileWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;

public class Simulation extends ApplicationAdapter {
    private final String scenarioPath;
    private final String outputPath;
    private final CountDownLatch latch;

    private int totalTicks;
    private int gravityX, gravityY;
    private int floorY;
    private List<int[]> spawns = new ArrayList<>(); // tick, x, y, vx, vy

    private Pool<Projectile> pool;
    private Array<Projectile> active;
    private int currentTick = 0;
    private int totalSpawned = 0;
    private int totalGrounded = 0;
    private int peakActive = 0;

    private Writer writer;

    public Simulation(String scenarioPath, String outputPath, CountDownLatch latch) {
        this.scenarioPath = scenarioPath;
        this.outputPath = outputPath;
        this.latch = latch;
    }

    @Override
    public void create() {
        FileHandle file = Gdx.files.absolute(scenarioPath);
        BufferedReader reader = new BufferedReader(file.reader("UTF-8"));
        try {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] parts = line.split("\\s+");
                switch (parts[0]) {
                    case "TICKS":
                        totalTicks = Integer.parseInt(parts[1]);
                        break;
                    case "GRAVITY":
                        gravityX = Integer.parseInt(parts[1]);
                        gravityY = Integer.parseInt(parts[2]);
                        break;
                    case "FLOOR":
                        floorY = Integer.parseInt(parts[1]);
                        break;
                    case "SPAWN":
                        int tick = Integer.parseInt(parts[1]);
                        int x = Integer.parseInt(parts[2]);
                        int y = Integer.parseInt(parts[3]);
                        int vx = Integer.parseInt(parts[4]);
                        int vy = Integer.parseInt(parts[5]);
                        spawns.add(new int[]{tick, x, y, vx, vy});
                        break;
                }
            }
            reader.close();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        pool = new Pool<Projectile>() {
            @Override
            protected Projectile newObject() {
                return new Projectile();
            }
        };
        active = new Array<>();

        try {
            writer = new FileWriter(outputPath);
            writer.write("TICKS " + totalTicks + "\n");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    public void render() {
        if (currentTick >= totalTicks) {
            return;
        }

        // 1. Spawn projectiles scheduled for this tick
        for (int[] spawn : spawns) {
            if (spawn[0] == currentTick) {
                Projectile p = pool.obtain();
                p.init(totalSpawned, spawn[1], spawn[2], spawn[3], spawn[4]);
                active.add(p);
                totalSpawned++;
            }
        }

        // 2. Apply gravity and integrate
        for (Projectile p : active) {
            p.velocity.x += gravityX;
            p.velocity.y += gravityY;
            p.position.x += p.velocity.x;
            p.position.y += p.velocity.y;
        }

        // 3. Ground projectiles with y <= floorY
        Array<Projectile> grounded = new Array<>();
        Array<Projectile> survivors = new Array<>();
        for (Projectile p : active) {
            if ((int)p.position.y <= floorY) {
                grounded.add(p);
            } else {
                survivors.add(p);
            }
        }
        // sort grounded by id (they should already be in order since active was in order)
        // active is in id order, so grounded is in id order

        for (Projectile p : grounded) {
            pool.free(p);
            totalGrounded++;
        }
        active = survivors;

        // Update peak
        if (active.size > peakActive) {
            peakActive = active.size;
        }

        // Write tick log
        try {
            StringBuilder sb = new StringBuilder();
            sb.append("TICK ").append(currentTick).append(" ACTIVE ").append(active.size).append("\n");
            for (Projectile p : active) {
                sb.append("P").append(p.id)
                  .append(" x=").append((int)p.position.x)
                  .append(" y=").append((int)p.position.y)
                  .append(" vx=").append((int)p.velocity.x)
                  .append(" vy=").append((int)p.velocity.y)
                  .append("\n");
            }
            for (Projectile p : grounded) {
                sb.append("GROUNDED P").append(p.id).append(" tick=").append(currentTick).append("\n");
            }
            writer.write(sb.toString());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        currentTick++;
        if (currentTick >= totalTicks) {
            // Write summary
            try {
                writer.write("SUMMARY spawned=" + totalSpawned + " grounded=" + totalGrounded
                    + " pool_free=" + pool.getFree() + " peak_active=" + peakActive + "\n");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            Gdx.app.exit();
        }
    }

    @Override
    public void dispose() {
        try {
            if (writer != null) writer.close();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        latch.countDown();
    }
}
```

